package data.scripts.orders.picker;
import com.fs.starfarer.api.combat.*; import data.scripts.orders.*; import org.lazywizard.lazylib.CollectionUtils; import java.util.*;
public class SpreadPicker extends NearestPicker { public AssignmentTargetAPI pick(ShipAPI s,List<CombatEntityAPI> t,CombatAssignmentType type,CombatEngineAPI e){t.sort(new CollectionUtils.SortEntitiesByDistance(s.getLocation()));CombatTaskManagerAPI tasks=e.getFleetManager(s.getOwner()).getTaskManager(s.isAlly());for(CombatEntityAPI x:t){AssignmentTargetAPI a=x instanceof ShipAPI?e.getFleetManager(x.getOwner()).getDeployedFleetMember((ShipAPI)x):(AssignmentTargetAPI)x;if(tasks.getAssignmentFor(s)!=null&&tasks.getAssignmentFor(s).getTarget()==a&&BattleNext_OrderUtils.assignmentCount(a,tasks)<=1)return a;if(BattleNext_OrderUtils.assignmentCount(a,tasks)==0)return a;}return super.pick(s,t,type,e);} }
